=== loader.c ===
/* See loader.h. Reads the app ELF via newlib's ordinary open/read/lseek --
 * already wired to HTIF by ../vplat_syscalls.c (the same file I/O vplat
 * uses), so this file carries no HTIF-specific code at all. */
#include "loader.h"

#include <elf.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>

#include "../htif_client.h" /* HTIF_SIM_CONTROL_BASE/_SIZE */
#include "hybrid/state_abi.h" /* HYBRID_V_SCRATCH_BYTES */
#include "vlinux_mem.h" /* U10c: ram_base-aware layout helpers */

#define LOADER_MAX_PHDRS 32

/* vlinux's own region bounds (runtime/linux/vlinux.ld): one source of
 * truth, not duplicated here as magic addresses. */
extern char _vlinux_base[];
extern char _stack[];

static int range_overlaps(uint64_t vaddr, uint64_t memsz, uint64_t base,
                          uint64_t end)
{
  return vaddr < end && (vaddr + memsz) > base;
}

/* Reject a PT_LOAD segment that would land on vlinux's own image, the
 * V-transport scratch page, or the HTIF MMIO window -- ROADMAP_LINUX_RUNTIME.md
 * U9: the V-scratch/window checks were deferred from U3 until a mode that
 * actually reserves them (hybrid) existed to test against, but run
 * unconditionally here since they are harmless (nothing is ever there
 * under fast/cycle) and correctness should not depend on which mode
 * booted this image. */
static int overlaps_reserved(uint64_t vaddr, uint64_t memsz, uint64_t ram_base,
                             uint64_t mem_size)
{
  const uint64_t vlinux_base = (uint64_t) (uintptr_t) _vlinux_base;
  const uint64_t vlinux_end = (uint64_t) (uintptr_t) _stack;
  if (range_overlaps(vaddr, memsz, vlinux_base, vlinux_end)) return 1;

  const uint64_t scratch_base = vlinux_v_scratch_base(ram_base, mem_size);
  if (range_overlaps(vaddr, memsz, scratch_base,
                     vlinux_ram_top(ram_base, mem_size)))
    return 1;

  if (range_overlaps(vaddr, memsz, HTIF_SIM_CONTROL_BASE,
                     HTIF_SIM_CONTROL_BASE + HTIF_SIM_CONTROL_SIZE))
    return 1;

  return 0;
}

static int read_full(int fd, void* buf, size_t len)
{
  char* p = (char*) buf;
  while (len > 0) {
    ssize_t n = read(fd, p, len);
    if (n <= 0) return -1;
    p += n;
    len -= (size_t) n;
  }
  return 0;
}

int load_elf(const char* path, uint64_t ram_base, uint64_t mem_size,
             struct loaded_elf* out)
{
  int fd = open(path, O_RDONLY);
  if (fd < 0) return -1;

  Elf64_Ehdr eh;
  if (read_full(fd, &eh, sizeof(eh)) < 0) goto fail;
  if (eh.e_ident[EI_MAG0] != ELFMAG0 || eh.e_ident[EI_MAG1] != ELFMAG1 ||
      eh.e_ident[EI_MAG2] != ELFMAG2 || eh.e_ident[EI_MAG3] != ELFMAG3 ||
      eh.e_ident[EI_CLASS] != ELFCLASS64 || eh.e_machine != EM_RISCV)
    goto fail;
  if (eh.e_phnum == 0 || eh.e_phnum > LOADER_MAX_PHDRS) goto fail;

  Elf64_Phdr phdrs[LOADER_MAX_PHDRS];
  if (lseek(fd, (off_t) eh.e_phoff, SEEK_SET) < 0) goto fail;
  if (read_full(fd, phdrs, (size_t) eh.e_phnum * sizeof(Elf64_Phdr)) < 0)
    goto fail;

  uint64_t phdr_vaddr = 0;
  uint64_t image_end = 0;
  for (unsigned i = 0; i < eh.e_phnum; ++i) {
    const Elf64_Phdr* ph = &phdrs[i];
    if (ph->p_type != PT_LOAD) continue;
    if (overlaps_reserved(ph->p_vaddr, ph->p_memsz, ram_base, mem_size))
      goto fail;

    if (lseek(fd, (off_t) ph->p_offset, SEEK_SET) < 0) goto fail;
    if (read_full(fd, (void*) (uintptr_t) ph->p_vaddr, ph->p_filesz) < 0)
      goto fail;
    if (ph->p_memsz > ph->p_filesz)
      memset((void*) (uintptr_t) (ph->p_vaddr + ph->p_filesz), 0,
             ph->p_memsz - ph->p_filesz);

    /* AT_PHDR: the program headers' address AS LOADED. Find the PT_LOAD
     * segment whose FILE range covers e_phoff and translate by the same
     * offset -- the segment does not necessarily start at the link base
     * (ld backs up to fit the ELF header + phdrs on the same page). */
    if (phdr_vaddr == 0 && eh.e_phoff >= ph->p_offset &&
        eh.e_phoff < ph->p_offset + ph->p_filesz)
      phdr_vaddr = ph->p_vaddr + (eh.e_phoff - ph->p_offset);

    const uint64_t seg_end = ph->p_vaddr + ph->p_memsz;
    if (seg_end > image_end) image_end = seg_end;
  }
  if (phdr_vaddr == 0) goto fail; /* no PT_LOAD covered the phdrs: malformed */

  close(fd);
  out->entry = eh.e_entry;
  out->phdr_vaddr = phdr_vaddr;
  out->phnum = eh.e_phnum;
  out->phentsize = eh.e_phentsize;
  out->image_end = image_end;
  return 0;

fail:
  close(fd);
  return -1;
}
=== mm.h ===
#ifndef VLINUX_MM_H
#define VLINUX_MM_H

#include <stdint.h>

/* Set the brk arena's floor (the app's own image end -- loaded_elf.image_end)
 * and the mmap arena's ceiling (vlinux_mem.h's vlinux_mmap_arena_top --
 * "just below the app stack", the roadmap's guest memory map). Guest RAM is
 * [ram_base, ram_base + mem_size); pass ram_base 0 for the historical
 * flat-from-zero map. Must be called once, before any sys_brk/sys_mmap. */
void mm_init(uint64_t app_image_end, uint64_t ram_base, uint64_t mem_size);

/* The manifest's guest RAM size, for sys_sysinfo's totalram/freeram. */
uint64_t mm_total_ram(void);

/* brk(2): addr==0 queries the current break; otherwise tries to set it.
 * Linux syscall convention: always returns the RESULTING break (old value
 * on failure, not -1) -- glibc's brk() wrapper compares it against what it
 * asked for. */
long sys_brk(unsigned long addr);

/* mmap(2): bump-allocates from the top of the mmap arena downward.
 * MAP_ANONYMOUS is zeroed (the POSIX guarantee); `addr` is ignored (no
 * MAP_FIXED support). MAP_PRIVATE file-backed (ROADMAP_LINUX_RUNTIME.md
 * U7, llama.cpp's default GGUF load path): the [offset, offset+length)
 * range is eagerly read (htif_pread) into the freshly-allocated arena
 * space -- a real, private, independently-owned COPY, which is exactly
 * what MAP_PRIVATE promises (writes never propagate back to the file;
 * there is simply nowhere for this relay to route them even if it wanted
 * to). Read-only MAP_SHARED (PROT_WRITE clear) is accepted the same way
 * -- llama.cpp maps GGUF files MAP_SHARED + PROT_READ -- since a mapping
 * nothing writes through is observably identical to MAP_PRIVATE; only a
 * WRITABLE MAP_SHARED request is refused (-ENOSYS), because this relay
 * has no way to write a shared mapping's changes back to the host file.
 * Returns a negative errno on failure, matching the raw syscall (not the
 * libc wrapper's -1 + errno) convention. */
long sys_mmap(unsigned long addr, unsigned long length, long prot,
             long flags, long fd, long offset);

/* munmap(2)/mprotect(2): the bump allocator never reclaims or changes
 * protection (there is no MMU here -- every page is already RWX), so both
 * are accepted no-ops for ANY address/length, mapped or not -- POSIX
 * itself allows this (munmap(2): "it is not an error if the indicated
 * range does not contain any mapped pages"), so llama.cpp's partial
 * unmap of an unused GGUF tail range is answered correctly without
 * needing to track individual mappings. A real munmap would let the
 * arena run out sooner than it should; that is a leak, not a crash. */
long sys_munmap(unsigned long addr, unsigned long length);
long sys_mprotect(unsigned long addr, unsigned long length, long prot);

/* mremap(2): always refused (-ENOMEM, ROADMAP_LINUX_RUNTIME.md U7) -- the
 * bump allocator has no in-place-grow or relocate-and-copy capability, so
 * a caller (llama.cpp does not use this for GGUF loading) gets a loud,
 * correct failure instead of silent corruption. */
long sys_mremap(unsigned long old_addr, unsigned long old_size,
                unsigned long new_size, unsigned long flags);

#endif /* VLINUX_MM_H */

